SELECT p.gender, p.age, s.status, i.icu_stay_id, i.intime, i.outtime, i.los, i.deathtime, v.vital_instability_index, t.tachycardia, m.map_value, m.burden_score, r.region, COUNT(DISTINCT i.hadm_id) AS num_patients FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.subject_id = i.subject_id JOIN vitals v ON a.subject_id = v.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND l.labtest_id = 10175 AND l.value < 65 JOIN tachycardia t ON a.subject_id = t.subject_id AND t.start_time BETWEEN i.intime AND i.outtime JOIN morbidity m ON a.subject_id = m.subject_id AND m.start_time BETWEEN i.intime AND i.outtime JOIN regions r ON r.region_id = i.careunit WHERE p.gender = 'F' AND p.age BETWEEN 63 AND 73 AND s.status = 'epilepticus' AND i.intime <= '2020-01-01' AND i.outtime >= '2020-12-31' AND v.vital_instability_index IS NOT NULL AND t.tachycardia IS NOT NULL AND m.map_value IS NOT NULL GROUP BY p.gender, p.age, s.status, i.icu_stay_id, i.intime, i.outtime, i.los, i.deathtime, v.vital_instability_index, t.tachycardia, m.map_value, m.burden_score, r.region;